use super::region;
use crate::{
    native::runtime::{
        Result,
        compute::{ComputeBatch, ResourceId},
    },
    shared::filter_config::FilterConfig,
};

/// Geometry borrowed from the owning Scene's validated scan buffers. Layer
/// consumers share that preparation contract instead of uploading a second copy.
#[derive(Clone, Copy)]
pub struct Geometry {
    bindings: [(u32, ResourceId); 6],
    shadow_base: u32,
    draw_count: u32,
}

impl Geometry {
    /// Bind geometry already generated by scan, without a CPU round trip.
    /// # Safety
    /// All handles must belong to one batch. Scan must precede every consumer;
    /// draw/path/paint records and scan capacities must cover the logical scene.
    pub(in crate::native::runtime::program) unsafe fn from_scan(
        draws: ResourceId,
        scan: &crate::native::runtime::program::scene_scan::ScanOutput,
        paint: ResourceId,
        draw_count: u32,
        shadow_base: u32,
    ) -> Self {
        Self {
            bindings: [
                (20, draws),
                (21, scan.paths),
                (22, scan.backdrops),
                (23, scan.tile_segment_ranges),
                (24, scan.segments),
                (10, paint),
            ],
            shadow_base,
            draw_count,
        }
    }

    pub(super) fn bindings(&self) -> &[(u32, ResourceId)] {
        &self.bindings
    }
    pub(super) fn shadow_base(&self) -> u32 {
        self.shadow_base
    }
    pub fn mask(
        &self,
        batch: &mut ComputeBatch,
        mut config: FilterConfig,
        tiles: Option<&[u32]>,
        target: ResourceId,
    ) -> Result<()> {
        if config.width > i32::MAX as u32 || config.height > i32::MAX as u32 {
            return Err("layer pixel coordinates exceed signed range".into());
        }
        // Allocation padding is not a live draw, and INVALID_INDEX is not an
        // empty mask. Reject missing references before allocating or recording.
        if config.draw_ix >= self.draw_count {
            return Err("layer mask exceeds logical draw range".into());
        }
        config.paint_sdf_shadow_base = self.shadow_base;
        region::record(
            batch,
            "filter_layer_mask_region",
            region::Geometry::Pixels,
            config,
            tiles,
            region::ReadBindings {
                images: None,
                buffers: &self.bindings,
                ..Default::default()
            },
            target,
        )
    }
}
